j:jelly.script:
function openFieldValuePicker(){
	var field = document.getElementById("promin_finding_def_condition.field");
	var fieldLabel = field.options[field.selectedIndex].text;

	var gm = new GlideModal('po_select_finding_rule_value');
	gm.setTitle("Select '"+fieldLabel +"' field value"); 
	gm.setPreference('sysparm_table', g_form.getValue("promin_finding_def_condition.table"));
	gm.setPreference('sysparm_field', g_form.getValue("promin_finding_def_condition.field")); 	
	gm.setPreference('sysparm_fieldLabel', fieldLabel);
	gm.setPreference('sysparm_defaultValue', g_form.getValue("field_value") || "");
	gm.setPreference('sysparm_defaultDisplayValue', g_form.getValue("field_display_value") || "");
	gm.setPreference('sysparm_displayFieldName', "field_display_value");
	gm.setPreference('sysparm_fieldName', "field_value");
	gm.setWidth(550);
	gm.render();
}
